#!/usr/bin/env python3
# Generated by Claude (Opus 5.5), 2026-10-17
"""Send a known ITCH 5.0 / MoldUDP64 feed over UDP, then print what the receiver should report.

Message mix, cycling: P trade, E executed, C printable, C non-printable, A add order.
Only P, E and printable C become Ticks in itch-parser.hpp. The last packet is
end-of-session, so ItchParser::start() returns on its own.
"""

import argparse
import socket
import struct

SESSION = b"SMOKETEST1"            # 10 bytes
START_TS_NS = 34_200 * 10**9       # 09:30:00, nanoseconds after midnight
STEP_NS = 1_000_000                # 1 ms between messages
STOCK = b"AAPL    "                # 8 bytes, space padded
LOCATE = 1
PRICE = 1_234_500                  # 123.4500, 4 implied decimals


def header(kind, ts_ns):
    # type(1) stock locate(2) tracking number(2) timestamp(6)
    return kind + struct.pack(">HH", LOCATE, 0) + ts_ns.to_bytes(6, "big")


def message(i):
    """Return (bytes, qty counted as a Tick or 0)."""
    ts = START_TS_NS + i * STEP_NS
    qty = 1 + i % 100
    ref = i + 1
    match = i + 1
    kind = i % 5
    if kind == 0:   # P: ref(8) side(1) shares(4) stock(8) price(4) match(8)
        return header(b"P", ts) + struct.pack(">QcI8sIQ", ref, b"B", qty, STOCK, PRICE, match), qty
    if kind == 1:   # E: ref(8) shares(4) match(8)
        return header(b"E", ts) + struct.pack(">QIQ", ref, qty, match), qty
    if kind == 2:   # C printable: ref(8) shares(4) match(8) printable(1) price(4)
        return header(b"C", ts) + struct.pack(">QIQcI", ref, qty, match, b"Y", PRICE), qty
    if kind == 3:   # C non-printable: decoded but not a Tick
        return header(b"C", ts) + struct.pack(">QIQcI", ref, qty, match, b"N", PRICE), 0
    # A: ref(8) side(1) shares(4) stock(8) price(4), not a Tick
    return header(b"A", ts) + struct.pack(">QcI8sI", ref, b"S", qty, STOCK, PRICE), 0


def packet(sequence, messages, count=None):
    body = b"".join(struct.pack(">H", len(m)) + m for m in messages)
    return SESSION + struct.pack(">QH", sequence, len(messages) if count is None else count) + body


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--host", default="127.0.0.1")
    ap.add_argument("--port", type=int, default=12345)
    ap.add_argument("--messages", type=int, default=1000)
    ap.add_argument("--per-packet", type=int, default=10)
    ap.add_argument("--drop-packet", type=int, default=None, metavar="N",
                    help="do not send data packet N (0-based) to exercise gap detection")
    args = ap.parse_args()

    msgs = [message(i) for i in range(args.messages)]
    chunks = [msgs[i:i + args.per_packet] for i in range(0, len(msgs), args.per_packet)]

    if args.drop_packet is not None and args.drop_packet == len(chunks) - 1:
        print("warning: dropping the last data packet is not detected as a gap, "
              "the end-of-session packet is not checked for sequence")

    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sent_packets = sent_messages = ticks = qty_sum = 0
    lost = 0
    sequence = 1                    # MoldUDP64 sequence numbers start at 1

    for n, chunk in enumerate(chunks):
        if n == args.drop_packet:
            if n != len(chunks) - 1:
                lost += len(chunk)
        else:
            sock.sendto(packet(sequence, [m for m, _ in chunk]), (args.host, args.port))
            sent_packets += 1
            sent_messages += len(chunk)
            ticks += sum(1 for _, q in chunk if q)
            qty_sum += sum(q for _, q in chunk)
        sequence += len(chunk)

    sock.sendto(packet(sequence, [], count=0xFFFF), (args.host, args.port))
    sent_packets += 1

    # Same field order as the println suggested for main.cpp
    print(f"expected: packets {sent_packets} messages {sent_messages} ticks {ticks} "
          f"lost {lost} malformed 0 sum {qty_sum}")


if __name__ == "__main__":
    main()
